+ */
+__attribute__((always_inline))
+static inline bool cache_ll_l1_is_icache_autoload_enabled(uint32_t cache_id)
+{
+    bool enabled = false;
+
+    if (cache_id == 0) {
+        enabled = REG_GET_BIT(CACHE_L1_ICACHE0_AUTOLOAD_CTRL_REG, CACHE_L1_ICACHE0_AUTOLOAD_ENA);
