function splitNorm(out) {
  const res={}; let cur=null;
  for (let line of out.output.split("\n")) {
    const h=line.match(/^[0-9a-f]+ <([^>]+)>:$/);
    if (h) { cur=h[1].split("+")[0]; if (!res[cur]) res[cur]=[]; continue; }
