   286	
   287	  /* Indicate that no interrupt sources are assigned to CPU interrupts */
   288	
   289	  for (i = 0; i < NR_IRQS; i++)
   290	    {
   291	      for (j = 0; j < CONFIG_SMP_NCPUS; j++)
   292	        {
   293	          g_handle_map[j][i] = IRQ_UNMAPPED;
   294	        }
   295	    }
