   302	
   303	#ifdef CONFIG_ESPRESSIF_GPIO_IRQ
   304	  esp_gpioirqinitialize();
   305	#endif
   306	
   307	  /* Initialize RTCIO interrupt support */
   308	
   309	  esp_rtcioirqinitialize();
   310	
   311	  /* Attach the common interrupt handler */
   312	
   313	  riscv_exception_attach();
   314	
   315	#ifndef CONFIG_SUPPRESS_INTERRUPTS
   316	
   317	  irq_attach(ESP_IRQ_DEMUX, esp_isr_demultiplexing, NULL);
   318	
   319	  /* And finally, enable interrupts */
   320	
   321	  riscv_color_intstack();
