   594	 * Name: riscv_dispatch_irq
   595	 *
   596	 * Description:
   597	 *   Process interrupt and its callback function.
   598	 *
   599	 * Input Parameters:
   600	 *   mcause        - RISC-V "mcause" register.
   601	 *   regs          - Saved registers reference.
   602	 *
   603	 * Returned Value:
   604	 *   None.
   605	 *
   606	 ****************************************************************************/
   607	
   608	IRAM_ATTR void *riscv_dispatch_irq(uintreg_t mcause, uintreg_t *regs)
   609	{
   610	  int irq;
   611	  bool is_irq = (RISCV_IRQ_BIT & mcause) != 0;
   612	  bool is_edge = false;
   613	  uint32_t cpu = esp_cpu_get_core_id();
   614	
   615	  if (is_irq)
   616	    {
   617	#ifdef CONFIG_ARCH_CHIP_ESP32P4
   618	      uint8_t cpuint = (mcause & VECTORS_MCAUSE_REASON_MASK) -
   619	                       RV_EXTERNAL_INT_OFFSET;
   620	#else
   621	      uint8_t cpuint = mcause & RISCV_IRQ_MASK;
   622	#endif
   623	
   624	      DEBUGASSERT(cpuint >= 0 && cpuint < ESP_NCPUINTS);
   625	      DEBUGASSERT(CPUINT_ISENABLED(g_cpuint_map[cpuint]));
   626	      DEBUGASSERT(CPUINT_ISASSIGNED(g_cpuint_map[cpuint]));
   627	
   628	      irq = g_cpuint_map[cpuint].irq;
   629	
   630	#ifdef CONFIG_ESPRESSIF_IRAM_ISR_DEBUG
   631	      /* Check if non-IRAM interrupts are disabled */
   632	
   633	      if (esp_irq_noniram_status(cpu) == 0)
   634	        {
   635	          /* Sum-up the IRAM-enabled counter associated with the IRQ */
   636	
   637	          esp_irq_iram_interrupt_record(irq);
   638	        }
   639	#endif
   640	
   641	      is_edge = esprv_int_get_type(cpuint) == INTR_TYPE_LEVEL;
   642	      if (is_edge)
   643	        {
   644	          /* Clear edge interrupts. */
   645	
   646	          esp_cpu_intr_edge_ack(cpuint);
   647	        }
   648	    }
   649	  else
   650	    {
   651	      /* It's exception */
   652	
   653	#ifdef CONFIG_ARCH_CHIP_ESP32P4
   654	      irq = mcause &
   655	            (VECTORS_MCAUSE_INTBIT_MASK | VECTORS_MCAUSE_REASON_MASK);
   656	#else
   657	      irq = mcause;
   658	#endif
   659	    }
   660	
   661	  regs = riscv_doirq(irq, regs);
   662	
   663	  return regs;
   664	}
