   185	    slowclk_cycles /= (cal_clk_sel == CLK_CAL_RTC_SLOW) ? 1 : CLK_CAL_DIV_VAL(cal_clk_sel);
   186	    assert(slowclk_cycles);
   187	    soc_xtal_freq_t xtal_freq = rtc_clk_xtal_freq_get();
   188	    uint64_t xtal_cycles = rtc_clk_cal_internal(cal_clk_sel, slowclk_cycles);
   189	
   190	    if (cal_clk_sel == CLK_CAL_32K_XTAL && !rtc_clk_cal_32k_valid((uint32_t)xtal_freq, slowclk_cycles, xtal_cycles)) {
   191	        return 0;
   192	    }
   193	
   194	    uint64_t divider = ((uint64_t)xtal_freq) * slowclk_cycles;
   195	    uint64_t period_64 = ((xtal_cycles << RTC_CLK_CAL_FRACT) + divider / 2 - 1) / divider;
   196	    uint32_t period = (uint32_t)(period_64 & UINT32_MAX);
   197	    return period;
   198	}
   199	
   200	uint64_t rtc_time_us_to_slowclk(uint64_t time_in_us, uint32_t period)
   201	{
   202	    assert(period);
   203	    if (time_in_us > (UINT64_MAX >> RTC_CLK_CAL_FRACT)) {
   204	        return ((time_in_us / period) << RTC_CLK_CAL_FRACT) + ((time_in_us % period) << RTC_CLK_CAL_FRACT) / period;
   205	    }
   206	    return (time_in_us << RTC_CLK_CAL_FRACT) / period;
   207	}
   208	
   209	uint64_t rtc_time_slowclk_to_us(uint64_t rtc_cycles, uint32_t period)
   210	{
   211	    return (rtc_cycles * period) >> RTC_CLK_CAL_FRACT;
   212	}
