   402	void rtc_clk_cpu_freq_set_config(const rtc_cpu_freq_config_t *config)
   403	{
   404	    soc_cpu_clk_src_t old_cpu_clk_src = clk_ll_cpu_get_src();
   405	    if (config->source == SOC_CPU_CLK_SRC_XTAL) {
   406	        rtc_clk_cpu_freq_to_xtal(config->freq_mhz, config->div.integer, false);
   407	        if (old_cpu_clk_src == SOC_CPU_CLK_SRC_CPLL) {
   408	            rtc_clk_cpll_disable();
   409	        }
   410	    } else if (config->source == SOC_CPU_CLK_SRC_CPLL) {
   411	        if (old_cpu_clk_src != SOC_CPU_CLK_SRC_CPLL) {
   412	            rtc_clk_set_cpu_switch_to_pll(SLEEP_EVENT_HW_PLL_EN_START);
   413	            rtc_clk_cpll_enable();
   414	        }
   415	        if (config->source_freq_mhz != s_cur_cpll_freq) {
   416	            soc_xtal_freq_t xtal_freq_mhz = rtc_clk_xtal_freq_get();
   417	            // Calibrate CPLL freq to a new value requires to switch CPU clock source to XTAL first
   418	            rtc_clk_cpu_freq_to_xtal((uint32_t)xtal_freq_mhz, 1, false);
   419	            rtc_clk_cpll_configure(xtal_freq_mhz, config->source_freq_mhz);
   420	        }
   421	        rtc_clk_cpu_freq_to_cpll_mhz(config->freq_mhz, (hal_utils_clk_div_t *)&config->div);
   422	        rtc_clk_set_cpu_switch_to_pll(SLEEP_EVENT_HW_PLL_EN_STOP);
   423	    } else if (config->source == SOC_CPU_CLK_SRC_RC_FAST) {
   424	        rtc_clk_cpu_freq_to_rc_fast();
   425	        if (old_cpu_clk_src == SOC_CPU_CLK_SRC_CPLL) {
   426	            rtc_clk_cpll_disable();
   427	        }
   428	    }
   429	}
