   431	static uint32_t rtc_clk_hp_root_get_freq_mhz(soc_cpu_clk_src_t clk_src)
   432	{
   433	    uint32_t source_freq_mhz = 0;
   434	    switch (clk_src) {
   435	    case SOC_CPU_CLK_SRC_XTAL:
   436	        source_freq_mhz = (uint32_t)rtc_clk_xtal_freq_get();
   437	        break;
   438	    case SOC_CPU_CLK_SRC_CPLL:
   439	        source_freq_mhz = clk_ll_cpll_get_freq_mhz((uint32_t)rtc_clk_xtal_freq_get());
   440	        break;
   441	    case SOC_CPU_CLK_SRC_RC_FAST:
   442	        source_freq_mhz = 20;
   443	        break;
   444	    default:
   445	        // Unknown HP_ROOT clock source
   446	        ESP_HW_LOGE(TAG, "Invalid HP_ROOT_CLK");
   447	        break;
   448	    }
   449	    return source_freq_mhz;
   450	}
