   452	void rtc_clk_cpu_freq_get_config(rtc_cpu_freq_config_t *out_config)
   453	{
   454	    soc_cpu_clk_src_t source = clk_ll_cpu_get_src();
   455	    uint32_t source_freq_mhz = rtc_clk_hp_root_get_freq_mhz(source);
   456	    if (source_freq_mhz == 0) {
   457	        // unsupported frequency configuration
   458	        abort();
   459	    }
   460	    hal_utils_clk_div_t div = {0}; // div = freq of SOC_ROOT_CLK / freq of CPU_CLK
   461	    clk_ll_cpu_get_divider(&div.integer, &div.numerator, &div.denominator);
   462	    if (div.denominator == 0) {
   463	        div.denominator = 1;
   464	        div.numerator = 0;
   465	    }
   466	    uint32_t freq_mhz = source_freq_mhz * div.denominator / (div.integer * div.denominator + div.numerator);
   467	    *out_config = (rtc_cpu_freq_config_t) {
   468	        .source = source,
   469	        .source_freq_mhz = source_freq_mhz,
   470	        .div = div,
   471	        .freq_mhz = freq_mhz
   472	    };
   473	}
