   477	    if (config->source == SOC_CPU_CLK_SRC_XTAL) {
   478	        rtc_clk_cpu_freq_to_xtal(config->freq_mhz, config->div.integer, false);
   479	    } else if (config->source == SOC_CPU_CLK_SRC_CPLL &&
   480	               s_cur_cpll_freq == config->source_freq_mhz) {
   481	        rtc_clk_cpu_freq_to_cpll_mhz(config->freq_mhz, (hal_utils_clk_div_t *)&config->div);
   482	    } else if (config->source == SOC_CPU_CLK_SRC_RC_FAST) {
   483	        rtc_clk_cpu_freq_to_rc_fast();
   484	    } else {
   485	        /* fallback */
   486	        rtc_clk_cpu_freq_set_config(config);
   487	    }
   488	}
