    66	#endif
    67	
    68	#ifdef CONFIG_BOOTLOADER_WDT_ENABLE
    69	    // WDT uses a SLOW_CLK clock source. After a function select_rtc_slow_clk a frequency of this source can changed.
    70	    // If the frequency changes from 150kHz to 32kHz, then the timeout set for the WDT will increase 4.6 times.
    71	    // Therefore, for the time of frequency change, set a new lower timeout value (1.6 sec).
    72	    // This prevents excessive delay before resetting in case the supply voltage is drawdown.
    73	    // (If frequency is changed from 150kHz to 32kHz then WDT timeout will increased to 1.6sec * 150/32 = 7.5 sec).
    74	    wdt_hal_context_t rtc_wdt_ctx = RWDT_HAL_CONTEXT_DEFAULT();
    75	    uint32_t stage_timeout_ticks = (uint32_t)(1600ULL * rtc_clk_slow_freq_get_hz() / 1000ULL);
    76	    wdt_hal_write_protect_disable(&rtc_wdt_ctx);
    77	    wdt_hal_feed(&rtc_wdt_ctx);
