    91	    stage_timeout_ticks = (uint32_t)((uint64_t)CONFIG_BOOTLOADER_WDT_TIME_MS * rtc_clk_slow_freq_get_hz() / 1000);
    92	    wdt_hal_write_protect_disable(&rtc_wdt_ctx);
    93	    wdt_hal_feed(&rtc_wdt_ctx);
    94	    wdt_hal_config_stage(&rtc_wdt_ctx, WDT_STAGE0, stage_timeout_ticks, WDT_STAGE_ACTION_RESET_RTC);
