   218	
   219	uint32_t rtc_clk_freq_cal(uint32_t cal_val)
   220	{
   221	    if (cal_val == 0) {
   222	        return 0;   // cal_val will be denominator, return 0 as the symbol of failure.
   223	    }
   224	    return 1000000ULL * (1 << RTC_CLK_CAL_FRACT) / cal_val;
   225	}
