   152	/****************************************************************************
   153	 * Name: esp_cpuint_alloc
   154	 *
   155	 * Description:
   156	 *   Allocate a free CPU interrupt for a peripheral device. This function
   157	 *   will not ignore all of the pre-allocated CPU interrupts for internal
   158	 *   devices.
   159	 *
   160	 * Input Parameters:
   161	 *   irq           - IRQ number.
   162	 *
   163	 * Returned Value:
   164	 *   On success, a CPU interrupt number is returned.
   165	 *   A negated errno is returned on failure.
   166	 *
   167	 ****************************************************************************/
   168	
   169	static int esp_cpuint_alloc(int irq)
   170	{
   171	  uint32_t bitmask;
   172	  uint32_t intset;
   173	  int cpuint = ESP_NCPUINTS;
   174	
   175	  /* Check if there are CPU interrupts with the requested properties
   176	   * available.
   177	   */
   178	
   179	  intset = g_cpuint_freelist;
   180	  if (intset != 0)
   181	    {
   182	      /* Skip over initial unavailable CPU interrupts quickly in groups
   183	       * of 8 interrupt.
   184	       */
   185	
   186	      for (cpuint = 0, bitmask = 0xff;
   187	           cpuint < ESP_NCPUINTS && (intset & bitmask) == 0;
   188	           cpuint += 8, bitmask <<= 8);
   189	
   190	      /* Search for an unallocated CPU interrupt number in the remaining
   191	       * intset.
   192	       */
   193	
   194	      for (; cpuint < ESP_NCPUINTS; cpuint++)
   195	        {
   196	          /* If the bit corresponding to the CPU interrupt is '1', then
   197	           * that CPU interrupt is available.
   198	           */
   199	
   200	          bitmask = BIT(cpuint);
   201	          if ((intset & bitmask) != 0)
   202	            {
   203	              /* Got it! */
   204	
   205	              g_cpuint_freelist &= ~bitmask;
   206	              break;
   207	            }
   208	        }
   209	    }
   210	
   211	  if (cpuint == ESP_NCPUINTS)
   212	    {
   213	      /* No unallocated CPU interrupt found */
   214	
   215	      return -ENOMEM;
   216	    }
   217	
   218	  DEBUGASSERT(CPUINT_ISFREE(g_cpuint_map[cpuint]));
   219	
   220	  esp_set_irq(irq, cpuint);
   221	
   222	  return cpuint;
   223	}
