   225	/****************************************************************************
   226	 * Name: esp_cpuint_free
   227	 *
   228	 * Description:
   229	 *   Free a previously allocated CPU interrupt.
   230	 *
   231	 * Input Parameters:
   232	 *   cpuint        - CPU interrupt to be freed.
   233	 *
   234	 * Returned Value:
   235	 *   None.
   236	 *
   237	 ****************************************************************************/
   238	
   239	static void esp_cpuint_free(int cpuint)
   240	{
   241	  uint32_t bitmask;
   242	
   243	  DEBUGASSERT(cpuint >= 0 && cpuint < ESP_NCPUINTS);
   244	  DEBUGASSERT(CPUINT_ISASSIGNED(g_cpuint_map[cpuint]));
   245	
   246	  int irq = CPUINT_GETIRQ(g_cpuint_map[cpuint]);
   247	  g_irq_map[irq] = IRQ_UNMAPPED;
   248	  CPUINT_FREE(g_cpuint_map[cpuint]);
   249	
   250	  /* Mark the CPU interrupt as available */
   251	
   252	  bitmask = BIT(cpuint);
   253	
   254	  DEBUGASSERT((g_cpuint_freelist & bitmask) == 0);
   255	
   256	  g_cpuint_freelist |= bitmask;
   257	}
