   259	/****************************************************************************
   260	 * Name: esp_cpuint_initialize
   261	 *
   262	 * Description:
   263	 *   Initialize CPU interrupts.
   264	 *
   265	 * Input Parameters:
   266	 *   None.
   267	 *
   268	 * Returned Value:
   269	 *   None.
   270	 *
   271	 ****************************************************************************/
   272	
   273	static void esp_cpuint_initialize(void)
   274	{
   275	  /* Unmap CPU interrupts from every interrupt source */
   276	
   277	  for (int source = 0; source < ESP_NSOURCES; source++)
   278	    {
   279	      esp_rom_route_intr_matrix(PRO_CPU_NUM, source, NO_CPUINT);
   280	    }
   281	
   282	  /* Set CPU interrupt threshold level */
   283	
   284	  esprv_int_set_threshold(RVHAL_INTR_ENABLE_THRESH);
   285	
   286	  /* Indicate that no interrupt sources are assigned to CPU interrupts */
   287	
   288	  memset(g_cpuint_map, 0, sizeof(g_cpuint_map));
   289	}
