   322	/****************************************************************************
   323	 * Name: up_irqinitialize
   324	 *
   325	 * Description:
   326	 *   Complete initialization of the interrupt system and enable normal,
   327	 *   interrupt processing.
   328	 *
   329	 * Input Parameters:
   330	 *   None.
   331	 *
   332	 * Returned Value:
   333	 *   None.
   334	 *
   335	 ****************************************************************************/
   336	
   337	void up_irqinitialize(void)
   338	{
   339	  /* All CPU ints are non-IRAM interrupts at the beginning and should be
   340	   * disabled during a SPI flash operation
   341	   */
   342	
   343	  for (int i = 0; i < CONFIG_SMP_NCPUS; i++)
   344	    {
   345	      non_iram_int_mask[i] = UINT32_MAX;
   346	    }
   347	
   348	  /* Indicate that no interrupt sources are assigned to CPU interrupts */
   349	
   350	  for (int i = 0; i < NR_IRQS; i++)
   351	    {
   352	      g_irq_map[i] = IRQ_UNMAPPED;
   353	    }
   354	
   355	  /* Initialize CPU interrupts */
   356	
   357	  esp_cpuint_initialize();
   358	
   359	  /* Initialize GPIO interrupt support */
   360	
   361	#ifdef CONFIG_ESPRESSIF_GPIO_IRQ
   362	  esp_gpioirqinitialize();
   363	#endif
   364	
   365	  /* Initialize RTCIO interrupt support */
   366	
   367	  esp_rtcioirqinitialize();
   368	
   369	  /* Attach the common interrupt handler */
   370	
   371	  riscv_exception_attach();
   372	
   373	#ifndef CONFIG_SUPPRESS_INTERRUPTS
   374	
   375	  /* And finally, enable interr…1125 tokens truncated…    78	 *
    79	 * Input Parameters:
    80	 *   irq           - IRQ associated to that interrupt.
    81	 *   context       - Interrupt register state save info.
    82	 *   arg           - A pointer to the argument provided when the interrupt
    83	 *                   was registered.
    84	 *
    85	 * Returned Value:
    86	 *   Zero on success; a negated errno value on failure.
    87	 *
    88	 ****************************************************************************/
    89	
    90	static int systimer_irq_handler(int irq, void *context, void *arg)
    91	{
    92	  static bool traced;
    93	  bool trace = !traced;
    94	
    95	  if (trace)
    96	    {
    97	      traced = true;
    98	      up_putc('X');
    99	    }
   100	
   101	  systimer_ll_clear_alarm_int(systimer_hal.dev,
   102	                              SYSTIMER_ALARM_OS_TICK_CORE0);
   103	
   104	#ifdef CONFIG_ARCH_CHIP_ESP32P4
   105	  /* Wait until the level interrupt is deasserted before returning through
   106	   * the CLIC.  Otherwise the same interrupt can be taken again immediately.
   107	   */
   108	
   109	  while (systimer_ll_is_alarm_int_fired(systimer_hal.dev,
   110	                                        SYSTIMER_ALARM_OS_TICK_CORE0))
   111	    {
   112	    }
   113	#endif
   114	
   115	  if (trace)
   116	    {
   117	      up_putc('Y');
   118	    }
   119	
   120	  /* Process timer interrupt */
   121	
   122	  nxsched_process_timer();
   123	
   124	  if (trace)
   125	    {
   126	      up_putc('Z');
   127	    }
   128	
   129	  return OK;
   130	}
