   136	/****************************************************************************
   137	 * Name: up_timer_initialize
   138	 *
   139	 * Description:
   140	 *   This function is called during start-up to initialize the timer
   141	 *   interrupt.
   142	 *
   143	 * Input Parameters:
   144	 *   None.
   145	 *
   146	 * Returned Value:
   147	 *   None.
   148	 *
   149	 ****************************************************************************/
   150	
   151	void up_timer_initialize(void)
   152	{
   153	  up_putc('0');
   154	#ifdef CONFIG_ARCH_CHIP_ESP32P4
   155	  PERIPH_RCC_ACQUIRE_ATOMIC(PERIPH_SYSTIMER_MODULE, ref_count)
   156	    {
   157	      if (ref_count == 0)
   158	        {
   159	          systimer_ll_enable_bus_clock(true);
   160	          systimer_ll_reset_register();
   161	        }
   162	    }
   163	#else
   164	  periph_module_enable(PERIPH_SYSTIMER_MODULE);
   165	#endif
   166	  up_putc('1');
   167	
   168	  systimer_hal_init(&systimer_hal);
   169	  systimer_hal_tick_rate_ops_t ops =
   170	    {
   171	      .ticks_to_us = systimer_ticks_to_us,
   172	      .us_to_ticks = systimer_us_to_ticks,
   173	    };
   174	
   175	  systimer_hal_set_tick_rate_ops(&systimer_hal, &ops);
   176	  systimer_ll_set_counter_value(systimer_hal.dev,
   177	                                SYSTIMER_COUNTER_OS_TICK,
   178	                                0);
   179	  systimer_ll_apply_counter_value(systimer_hal.dev,
   180	                                  SYSTIMER_COUNTER_OS_TICK);
   181	  systimer_hal_counter_can_stall_by_cpu(&systimer_hal,
   182	                                        SYSTIMER_COUNTER_OS_TICK, 0,
   183	                                        false);
   184	
   185	  systimer_hal_connect_alarm_counter(&systimer_hal,
   186	                                     SYSTIMER_ALARM_OS_TICK_CORE0,
   187	                                     SYSTIMER_COUNTER_OS_TICK);
   188	  systimer_hal_set_alarm_period(&systimer_hal,
   189	                                SYSTIMER_ALARM_OS_TICK_CORE0,
   190	                                CONFIG_USEC_PER_TICK);
   191	  systimer_hal_select_alarm_mode(&systimer_hal,
   192	                                 SYSTIMER_ALARM_OS_TICK_CORE0,
   193	                                 SYSTIMER_ALARM_MODE_PERIOD);
   194	  systimer_hal_counter_can_stall_by_cpu(&systimer_hal,
   195	                                        SYSTIMER_COUNTER_OS_TICK, 0,
   196	                                        true);
   197	  up_putc('2');
   198	  systimer_hal_enable_alarm_int(&systimer_hal,
   199	                                SYSTIMER_ALARM_OS_TICK_CORE0);
   200	  systimer_hal_enable_counter(&systimer_hal, SYSTIMER_COUNTER_OS_TICK);
   201	  up_putc('3');
   202	
   203	  esp_setup_irq(CHIP_SYSTIMER_SOURCE,
   204	                ESP_IRQ_PRIORITY_DEFAULT,
   205	                SYSTIMER_TRIGGER_TYPE);
   206	  up_putc('4');
   207	
   208	  /* Attach the timer interrupt. */
   209	
   210	  irq_attach(ESP_SOURCE2IRQ(CHIP_SYSTIMER_SOURCE),
   211	             (xcpt_t)systimer_irq_handler,
   212	             NULL);
   213	  up_putc('5');
   214	
   215	  /* Enable the allocated CPU interrupt. */
   216	
   217	  up_putc('6');
   218	  up_enable_irq(ESP_SOURCE2IRQ(CHIP_SYSTIMER_SOURCE));
   219	  up_putc('7');
   220	}
