   400	 ****************************************************************************/
   401	
   402	int esp_setup_irq(int source,
   403	                  irq_priority_t priority,
   404	                  int type,
   405	                  xcpt_t handler,
   406	                  void *arg)
   407	{
   408	  return esp_setup_irq_intrstatus(source, priority, type, 0, 0,
   409	                                  handler, arg);
   410	}
   411	
   412	int esp_setup_irq_with_flags(int source,
   413	                             int flags,
   414	                             xcpt_t handler,
   415	                             void *arg)
   416	{
   417	  return esp_setup_irq_with_flags_intrstatus(source, flags, 0, 0,
   418	                                             handler, arg);
   419	}
   420	
   421	int esp_setup_irq_intrstatus(int source,
   422	                             irq_priority_t priority,
   423	                             int type,
   424	                             uint32_t intrstatusreg,
   425	                             uint32_t intrstatusmask,
   426	                             xcpt_t handler,
   427	                             void *arg)
   428	{
   429	  int flags;
   430	
   431	  flags = (1 << priority);
   432	  flags |= type == ESP_IRQ_TRIGGER_EDGE ? ESP_INTR_FLAG_EDGE : 0;
   433	  flags |= ESP_INTR_FLAG_INTRDISABLED;
   434	
   435	  return esp_setup_irq_with_flags_intrstatus(source,
   436	                                             flags,
   437	                                             intrstatusreg,
   438	                                             intrstatusmask,
   439	                                             handler,
   440	                                             arg);
   441	}
   442	
   443	int esp_setup_irq_with_flags_intrstatus(int source,
   444	                                        int flags,
   445	                                        uint32_t intrstatusreg,
   446	                                        uint32_t intrstatusmask,
   447	                                        xcpt_t handler,
   448	                                        void *arg)
   449	{
   450	  struct intr_adapter_from_nuttx *isr_adapter_args;
   451	  esp_err_t ret;
   452	  intr_handle_t ret_handle;
   453	  int cpuint;
   454	  int irq;
   455	
   456	  irqinfo("source = %d\n", source);
   457	
   458	  isr_adapter_args = kmm_calloc(1, sizeof(struct intr_adapter_from_nuttx));
   459	  if (isr_adapter_args == NULL)
   460	    {
   461	      irqerr("Failed to kmm_calloc\n");
   462	      return -EINVAL;
   463	    }
   464	
   465	  isr_adapter_args->func = handler;
   466	  isr_adapter_args->arg = arg;
   467	
   468	  ret = esp_intr_alloc_intrstatus(source,
   469	                                  flags,
   470	                                  intrstatusreg,
   471	                                  intrstatusmask,
   472	                                  isr_adapter_func,
   473	                                  isr_adapter_args,
   474	                                  &ret_handle);
   475	  if (ret != ESP_OK)
   476	    {
   477	      irqerr("Failed to allocate interrupt for source %d\n", source);
   478	      kmm_free(isr_adapter_args);
   479	      return -EINVAL;
   480	    }
   481	
   482	  cpuint = esp_intr_get_intno(ret_handle);
   483	
   484	  if (source < 0)
   485	    {
   486	      irq = source + ETS_INTERNAL_INTR_SOURCE_OFF;
   487	    }
   488	  else
   489	    {
   490	      irq = ESP_SOURCE2IRQ(source);
   491	    }
   492	
   493	  /* Store the handle. The handle already contains the CPU interrupt and
   494	   * CPU information, so no additional mapping is needed.
   495	   */
   496	
   497	  esp_set_handle(this_cpu(), irq, ret_handle);
   498	
   499	  return cpuint;
   500	}
