   156	/****************************************************************************
   157	 * Name: esp_cpuint_alloc
   158	 *
   159	 * Description:
   160	 *   Allocate a free CPU interrupt for a peripheral device. This function
   161	 *   will not ignore all of the pre-allocated CPU interrupts for internal
   162	 *   devices.
   163	 *
   164	 * Input Parameters:
   165	 *   irq           - IRQ number.
   166	 *
   167	 * Returned Value:
   168	 *   On success, a CPU interrupt number is returned.
   169	 *   A negated errno is returned on failure.
   170	 *
   171	 ****************************************************************************/
   172	
   173	static int esp_cpuint_alloc(int irq)
   174	{
