   211	            }
   212	        }
   213	    }
   214	
   215	  if (cpuint == ESP_NCPUINTS)
   216	    {
   217	      /* No unallocated CPU interrupt found */
   218	
   219	      return -ENOMEM;
   220	    }
   221	
   222	  DEBUGASSERT(CPUINT_ISFREE(g_cpuint_map[cpuint]));
   223	
   224	  esp_set_irq(irq, cpuint);
   225	
   226	  return cpuint;
   227	}
